/**
 * Token value parity across the three outputs (CROSS-PLATFORM.md section 2 and section 8, item 8): every colour
 * role of every theme has the same value in the CSS (`buildMonarchCss`, what the web paints), in Swift
 * (`platforms/ios/Sources/MonarchTokens/MonarchTokens.swift`) and in Kotlin
 * (`platforms/android/monarch-tokens/.../MonarchTokens.kt`). The native files are generated by
 * `scripts/emit-native.ts` and checked for staleness by `native:tokens:check`; this test checks the values
 * themselves, so a change to one emitter that the others do not follow fails here.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { hsl, toHex } from '../src/color.js';
import { buildMonarchCss, themeSelectors } from '../src/css.js';
import { defaultAccent } from '../src/primitives.js';
import { THEME_IDS, type ThemeId } from '../src/themes.js';

const repo = join(fileURLToPath(new URL('.', import.meta.url)), '..', '..', '..');
const swift = readFileSync(
  join(repo, 'platforms/ios/Sources/MonarchTokens/MonarchTokens.swift'),
  'utf8',
);
const kotlin = readFileSync(
  join(
    repo,
    'platforms/android/monarch-tokens/src/main/kotlin/dev/monarchui/tokens/MonarchTokens.kt',
  ),
  'utf8',
);
const css = buildMonarchCss(defaultAccent);

/** `RRGGBB/AA`, upper case: the value every output is compared in. */
type Value = string;
const value = (rgb: string, alpha: number): Value =>
  `${rgb.toUpperCase()}/${Math.round(alpha * 255)
    .toString(16)
    .toUpperCase()
    .padStart(2, '0')}`;

const camelToKebab = (name: string) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([a-z])([0-9])/g, '$1-$2')
    .toLowerCase();
const nativeName: Record<ThemeId, string> = {
  light: 'light',
  dark: 'dark',
  'hc-light': 'hcLight',
  'hc-dark': 'hcDark',
};

/** The colour declarations of one theme's block of the stylesheet, aliases (`var(...)`) resolved. */
function cssColors(theme: ThemeId): Map<string, Value> {
  const selector = themeSelectors(theme).join(',\n  ');
  const declarations = new Map<string, string>();
  const read = (sel: string) => {
    const start = css.indexOf(`  ${sel} {\n`);
    if (start < 0) return;
    const body = css.slice(start, css.indexOf('\n  }', start));
    for (const m of body.matchAll(/^\s*(--mn-color-[a-z0-9-]+):\s*([^;]+);/gm)) {
      if (!declarations.has(m[1]!)) declarations.set(m[1]!, m[2]!.trim());
    }
  };
  read(selector);
  // A theme block holds what differs; anything else comes from the light block.
  if (theme !== 'light') read(themeSelectors('light').join(',\n  '));
  const resolve = (raw: string, depth = 0): Value | null => {
    const alias = /^var\((--mn-color-[a-z0-9-]+)\)$/.exec(raw);
    if (alias) {
      const target = declarations.get(alias[1]!);
      return target && depth < 8 ? resolve(target, depth + 1) : null;
    }
    const m = /^hsl\(([\d.]+) ([\d.]+)% ([\d.]+)%(?: \/ ([\d.]+))?\)$/.exec(raw);
    if (!m) return null;
    const hex = toHex(hsl(Number(m[1]), Number(m[2]), Number(m[3]))).slice(1);
    return value(hex, m[4] === undefined ? 1 : Number(m[4]));
  };
  const out = new Map<string, Value>();
  for (const [name, raw] of declarations) {
    const v = resolve(raw);
    if (v) out.set(name, v);
  }
  return out;
}

/** The colours of `MonarchTokens.<theme>` in Swift, by role. */
function swiftColors(theme: ThemeId): Map<string, Value> {
  const start = swift.indexOf(`public static let ${nativeName[theme]} = MonarchThemeTokens(`);
  expect(start, `Swift MonarchTokens.${nativeName[theme]}`).toBeGreaterThan(0);
  const end = swift.indexOf('public static let', start + 10);
  const body = swift.slice(start, end);
  const out = new Map<string, Value>();
  for (const m of body.matchAll(
    /^\s*(\w+): MonarchRGBA\(0x([0-9A-F]{6})(?:, alpha: ([\d.]+))?\)/gm,
  )) {
    out.set(m[1]!, value(m[2]!, m[3] === undefined ? 1 : Number(m[3])));
  }
  return out;
}

/** The colours of `MonarchTokens.<theme>` in Kotlin, by role. */
function kotlinColors(theme: ThemeId): Map<string, Value> {
  const start = kotlin.indexOf(
    `public val ${nativeName[theme]}: MonarchThemeTokens = MonarchThemeTokens(`,
  );
  expect(start, `Kotlin MonarchTokens.${nativeName[theme]}`).toBeGreaterThan(0);
  const end = kotlin.indexOf('public val', start + 10);
  const body = kotlin.slice(start, end);
  const out = new Map<string, Value>();
  for (const m of body.matchAll(/^\s*(\w+) = 0x([0-9A-F]{2})([0-9A-F]{6})L,/gm)) {
    out.set(m[1]!, `${m[3]}/${m[2]}`);
  }
  return out;
}

describe('colour roles are equal on the web, iOS and Android', () => {
  for (const theme of THEME_IDS) {
    it(`${theme}`, () => {
      const web = cssColors(theme);
      const ios = swiftColors(theme);
      const android = kotlinColors(theme);
      expect(ios.size, 'Swift colour roles').toBeGreaterThan(80);
      // The same roles on both native platforms.
      expect([...android.keys()].sort()).toEqual([...ios.keys()].sort());
      const differences: string[] = [];
      for (const [role, iosValue] of ios) {
        const webValue = web.get(`--mn-color-${camelToKebab(role)}`);
        if (webValue === undefined)
          differences.push(`${role}: no --mn-color-${camelToKebab(role)} in the CSS`);
        else if (webValue !== iosValue)
          differences.push(`${role}: web ${webValue}, iOS ${iosValue}`);
        if (android.get(role) !== iosValue)
          differences.push(`${role}: iOS ${iosValue}, Android ${android.get(role)}`);
      }
      expect(differences).toEqual([]);
    });
  }
});
